from django.apps import AppConfig

# This class is used to configure the catalog application. 
# This was automatically generated when the application was created using the "startapp" command.
class CatalogConfig(AppConfig):
    # the default_auto_field attribute specifies the type of primary key to use for models in this application.
    default_auto_field = 'django.db.models.BigAutoField'
    # the name attribute specifies the full Python path to the application.
    name = 'catalog'
